{% endif -%}
{% if Vorgang.Rechnungsadresse.Firmenzusatz != empty -%}
  {{ Vorgang.Rechnungsadresse.Firmenzusatz }}
{% endif -%}
  {% if Vorgang.Rechnungsadresse.Anrede != empty -%}
{{ Vorgang.Rechnungsadresse.Anrede }} \
{% endif -%}
{% if Vorgang.Rechnungsadresse.Titel != empty -%}
{{ Vorgang.Rechnungsadresse.Titel }} \
{% else -%}
{{ Vorgang.Rechnungsadresse.Vorname }} \
{% endif -%}
{% if Vorgang.Rechnungsadresse.Nachname != empty -%}
{{ Vorgang.Rechnungsadresse.Nachname }} \
{% endif %}
{% if Vorgang.Rechnungsadresse.Adresszusatz != empty -%}
{{ Vorgang.Rechnungsadresse.Adresszusatz }}
{% endif -%}
  {{ Vorgang.Rechnungsadresse.Straße }}
  {{ Vorgang.Rechnungsadresse.PLZ }} {{ Vorgang.Rechnungsadresse.Ort }}
{% if Vorgang.Rechnungsadresse.Landname != empty -%}
  {{ Vorgang.Rechnungsadresse.Landname }}
{% endif -%}
{% if Vorgang.AbweichendeAdressen == true or NurAbweichendeLieferadresse == false -%}

Lieferung an:
{% if Vorgang.Lieferadresse.Firma != empty -%}
  {{ Vorgang.Lieferadresse.Firma }}
{% endif -%}
{% if Vorgang.Lieferadresse.Firmenzusatz != empty -%}
  {{ Vorgang.Lieferadresse.Firmenzusatz }}
{% endif -%}
  {% if Vorgang.Lieferadresse.Anrede != empty -%}
{{ Vorgang.Lieferadresse.Anrede }} \
{% endif -%}
{% if Vorgang.Lieferadresse.Titel != empty -%}
{{ Vorgang.Lieferadresse.Titel }} \
{% else -%}
{{ Vorgang.Lieferadresse.Vorname }} \
{% endif -%}
{% if Vorgang.Lieferadresse.Nachname != empty -%}
{{ Vorgang.Lieferadresse.Nachname }}\
{% endif %}
{% if Vorgang.Lieferadresse.Adresszusatz != empty -%}
{{ Vorgang.Lieferadresse.Adresszusatz }}
{% endif -%}
  {{ Vorgang.Lieferadresse.Straße }}
  {{ Vorgang.Lieferadresse.PLZ }} {{ Vorgang.Lieferadresse.Ort }}
{% if Vorgang.Lieferadresse.Landname != empty -%}
  {{ Vorgang.Lieferadresse.Landname }}
{% endif -%}
{% endif -%}

Positionen:
{% for position in Vorgang.Positionen -%}
{% if position.MwStSatz != 0 or position.NettopreisGesamt >= 0 -%}
{% capture menge -%}
{% if position.VPEEinheit != empty -%}
{{ position.Menge | DividedBy: position.VPEMenge | Nummer: 'N4' }}\
{% else -%}
{% if position.Artikel.IstTeilbar -%}
{{ position.Menge | Nummer : 'N2' }}\
{% else -%}
{{ position.Menge }}\
{% endif -%}
{% endif -%}
{% if position.VPEEinheit != empty -%}
 {{ Position.VPEEinheit }}\
{% elsif position.Einheit != empty -%}
 {{ Position.Einheit }}\
{% else -%}
x\
{% endif %} {{ position.Lieferantenartikelbezeichnung }}{% endcapture -%}
  {{ menge | Truncate: 61 | Align: -61 }}{{Tabulator}}{{ position.NettopreisGesamt | Nummer: 'C2' | Align: 15 }}
{% capture info %}Art.Nr.: {{ position.Lieferantenartikelnummer }}, EZ-Preis: {% if position.VPEEinheit != empty %}{{ position.NettopreisEinzel | Times: position.VPEMenge | Nummer: 'C2' }}{% else %}{{ position.NettopreisEinzel | Nummer : 'C2' }}{% endif %}, USt-Satz: {{ position.MwStSatz | Nummber : 'N'}}% {% endcapture -%}
    {{ info | Truncate: 60 }}
{% endif -%}
{% endfor -%}
  {{ ' ' | Align: 60 }}{{Tabulator}}---------------
