{% if summe.Brutto > 0 or Vorgang.Summen.size == 1 -%}
{% capture desc %}Summe Netto ({{summe.UStSatz | Nummer : 'N' }}%):{% endcapture -%}
  {{ desc | Truncate: 60 | Align: 60 }}{{Tabulator}}{{ summe.Netto | Nummer : 'C2' | Align: 15 }}
{% endif -%}
{% endfor -%}
{% for summe in Vorgang.Summen -%}
{% if summe.Brutto > 0 or Vorgang.Summen.size == 1 -%}
{% capture desc %}zzgl. USt. ({{summe.UStSatz | Nummer : 'N' }}%):{% endcapture -%}
