{% endif -%}
{% endfor -%}
{% for position in Vorgang.Positionen -%}
{% if position.MwStSatz == 0 and position.NettopreisGesamt < 0 -%}
  {{ 'abzgl. Rabatt.:' | Trunace: 60 | Align: 60 }}{{Tabulator}}{{ position.NettopreisGesamt | Nummer:'C2' | Align: 15 }}
{% endif -%}
{% endfor -%}
  {{ ' ' | Align: 60 }}{{Tabulator}}===============
  {{ 'Gesamtsumme:' | Truncate: 60 | Align: 60 }}{{ Tabulator }}{{ Vorgang.Positionen.BruttopreisGesamt | Nummer : 'C2' | Align: 15 }}

{% if Vorgang.DruckAnmerkung != empty -%}
Anmerkungen:
  {{ Vorgang.DruckAnmerkung }}<br />

{% endif -%}  

Mit freundlichen Grüßen

{{ Vorgang.Benutzer.Name }}
{{ Vorgang.Firma.Name }}

---
{% if Vorgang.Firma.Homepage != empty %}
Besuchen Sie auf unserer Homepage unter {{Vorgang.Firma.Homepage}}.

{% endif -%}
{{ Vorgang.Firma.Name }}
{% if Vorgang.Firma.Unternehmer != empty -%}
{{ Vorgang.Firma.Unternehmer }}
{% endif -%}
{{ Vorgang.Firma.Straße }}
{{ Vorgang.Firma.PLZ }} {{ Vorgang.Firma.Ort }}
