{{ Vorgang.Firma.Landname }}
{% endif -%}
Tel: {{ Vorgang.Firma.Telefon }}
{% if Vorgang.Firma.Fax != empty -%}
Fax: {{ Vorgang.Firma.Fax }}
{% endif -%}             
